  ||Number(v.expiresAt)<=now||Number(v.issuedAt)>now+60000||Number(v.expiresAt)<=Number(v.issuedAt)||Number(v.expiresAt)-Number(v.issuedAt)>600000
  ||!Array.isArray(v.routes)||v.routes.length>64)invalid();
